clear; clc; close all;

% =========================================================================
% 1. LOAD DATA
% =========================================================================
% Replace these filenames with the specific trial you are analyzing
forceplate_filename = 'quietEO.txt'; 
emg_filename = 'quieteo.data'; 

% Load Force Plate data (Assuming 6 columns: Fx, Fy, Fz, Mx, My, Mz) 
fp_data = load(forceplate_filename); 
Fx = fp_data(:, 1);
Fy = fp_data(:, 2);
Fz = fp_data(:, 3);
Mx = fp_data(:, 4);
My = fp_data(:, 5);
Mz = fp_data(:, 6);

% Load EMG data (Assuming 2 columns: SOL and TA) [cite: 113]
% *Adjust the column indices if your .data file is formatted differently*
emg_data = load(emg_filename); 
SOL_raw = emg_data(:, 1); 
TA_raw = emg_data(:, 2);

% =========================================================================
% 2. CALCULATE AP FROM FORCE PLATE DATA
% =========================================================================
dz = 41.3; % force plate thickness in mm [cite: 133]

% Calculate Anterior-Posterior (AP) COP. 
% We use the Y-equation from the manual as it aligns with the AP axis[cite: 135].
AP_raw = (Mx - Fy .* dz) ./ Fz; 

% =========================================================================
% 3. INTERPOLATION (200 Hz to 960 Hz) [cite: 143]
% =========================================================================
% Create time vector for original force plate data (sampled at 200 Hz)
t_fp = (0:length(AP_raw)-1) / 200;

% Create time vector for the new interpolated data (960 Hz)
t_interp = 0:(1/960):t_fp(end);

% Interpolate AP to 960 Hz [cite: 144]
AP_interp = interp1(t_fp, AP_raw, t_interp, 'linear');

% Match array lengths (Since synchronization is skipped, we align from t=0)
min_length = min(length(AP_interp), length(SOL_raw));
AP_interp = AP_interp(1:min_length)';
SOL_raw = SOL_raw(1:min_length);
TA_raw = TA_raw(1:min_length);

% =========================================================================
% 4. FILTERING [cite: 215, 236]
% =========================================================================
% 4th order, 5 Hz cutoff, 960 Hz sampling rate (Nyquist = 480) [cite: 217]
[b, a] = butter(4, 5/480, 'low'); 

% Filter COP (AP) and subtract the mean (DC component) [cite: 216, 218]
AP_filt = filtfilt(b, a, AP_interp); 
AP_filt = AP_filt - mean(AP_filt); 

% Rectify raw EMG data [cite: 236]
SOL_rect = abs(SOL_raw);
TA_rect = abs(TA_raw);

% Filter rectified EMG (Do NOT subtract the mean for EMG) [cite: 236, 237]
SOL_filt = filtfilt(b, a, SOL_rect);
TA_filt = filtfilt(b, a, TA_rect);

figure;plot(SOL_filt) %[output:38a05162]
figure;plot(TA_filt) %[output:99059c55]
figure;plot(AP_filt) %[output:2187c646]
% =========================================================================
% 5. EXTRACT MIDDLE 60% OF THE DATA
% =========================================================================
N = length(AP_filt); % Total number of data points
idx_start = floor(0.20 * N) + 1; % Start index (skip first 20%)
idx_end = floor(0.80 * N);       % End index (skip last 20%)

% Extract the middle 60% of the signals
AP_mid = AP_filt(idx_start:idx_end);
SOL_mid = SOL_filt(idx_start:idx_end);
TA_mid = TA_filt(idx_start:idx_end);

% Remove the mean (DC offset) specifically for this new window 
% to ensure the signal is centered around zero for xcorr
AP_mid = AP_mid - mean(AP_mid);
SOL_mid = SOL_mid - mean(SOL_mid);
TA_mid = TA_mid - mean(TA_mid);

% =========================================================================
% 6. CCF CALCULATION (-20s to +20s)
% =========================================================================
freq = 960; 
maxlag_samples = 20 * freq; % 20 seconds converted to samples (19,200)

% Calculate Cross-Correlation for the entire middle block
% 'maxlag' limits the calculation to +/- 20 seconds
% 'coeff' normalizes the peak auto-correlation to 1 (bounds results to -1 to 1)
[ccf_SOL, lags] = xcorr(SOL_mid, AP_mid, maxlag_samples, 'coeff');
[ccf_TA, ~] = xcorr(TA_mid, AP_mid, maxlag_samples, 'coeff');

% Convert lag indices back to time in seconds
time_shift = lags / freq;

% =========================================================================
% 7. EXTRACT CVAL / TS AND PLOT RESULTS
% =========================================================================
% Find max CCF value (CVAL) and corresponding time shift (TS) for Soleus
[CVAL_SOL, max_idx_SOL] = max(ccf_SOL);
TS_SOL = time_shift(max_idx_SOL);

% Find max CCF value (CVAL) and corresponding time shift (TS) for TA
[CVAL_TA, max_idx_TA] = max(ccf_TA);
TS_TA = time_shift(max_idx_TA);

% Plot the new CCF results
figure('Name', 'Cross-Correlation Functions (Middle 60%, +/- 20s)', 'Position', [100, 100, 800, 600]); %[output:92ae8e4f]

% Subplot 1: AP vs SOL
subplot(2,1,1); %[output:92ae8e4f]
plot(time_shift, ccf_SOL, 'b', 'LineWidth', 1.2); hold on; %[output:92ae8e4f]
plot(TS_SOL, CVAL_SOL, 'r*', 'MarkerSize', 10, 'LineWidth', 1.5); %[output:92ae8e4f]
title(sprintf('CCF: AP vs SOL (CVAL = %.3f, TS = %.3f s)', CVAL_SOL, TS_SOL)); %[output:92ae8e4f]
xlabel('Time Shift (s)'); ylabel('Cross-Correlation');  %[output:92ae8e4f]
xlim([-20 20]); grid on; %[output:92ae8e4f]

% Subplot 2: AP vs TA
subplot(2,1,2); %[output:92ae8e4f]
plot(time_shift, ccf_TA, 'Color', [0 0.5 0], 'LineWidth', 1.2); hold on; %[output:92ae8e4f]
plot(TS_TA, CVAL_TA, 'r*', 'MarkerSize', 10, 'LineWidth', 1.5); %[output:92ae8e4f]
title(sprintf('CCF: AP vs TA (CVAL = %.3f, TS = %.3f s)', CVAL_TA, TS_TA)); %[output:92ae8e4f]
xlabel('Time Shift (s)'); ylabel('Cross-Correlation');  %[output:92ae8e4f]
xlim([-20 20]); grid on;% Note: A negative TS means the EMG signal precedes the COP displacement[cite: 249]. %[output:92ae8e4f]

